        // MARK: - CTRLA
        
        /// SPI Control A - CTRLA
        @inline(__always)
        static var controlA: UInt32 {
            get {
                _volatileRegisterReadUInt32(SERCOM1_BASE)
            }
            set {
                _volatileRegisterWriteUInt32(SERCOM1_BASE, newValue)
            }
