        static var intflagRXC: Bool {
            get { (SERCOM1.SPI.intflag & (1 << 2)) != 0 }
            set { if newValue { _volatileRegisterWriteUInt32(SERCOM1_BASE + 0x18, 1 << 2) } }
        }

